package com.flippingfriend.companion;
import org.junit.Test; import static org.junit.Assert.*;
public class BuyReplacementQuantityRoundTripCompletionEvaluatorTest {
 @Test public void productionFormulaEvaluatesEveryViableQuantityInOrder(){BuyReplacementQuantityFillViabilityAssessment s=source();BuyReplacementQuantityRoundTripCompletionEvaluationSet r=new BuyReplacementQuantityRoundTripCompletionEvaluator().evaluate(s,1100);assertNotNull(r);assertEquals(s.getViableCandidates().size(),r.getEvaluations().size());for(int i=0;i<r.getEvaluations().size();i++){BuyReplacementQuantityFillViableCandidate v=s.getViableCandidates().get(i);BuyReplacementQuantityRoundTripCompletionEvaluation e=r.getEvaluations().get(i);assertEquals(v.getBuyProbability()*v.getSellProbability(),e.getCompletionProbability(),0.0);assertEquals(v.getQuantity(),e.getQuantity());assertEquals(v.getSizeGridIndex(),e.getSizeGridIndex());}try{r.getEvaluations().clear();fail("immutable");}catch(UnsupportedOperationException expected){}}
 @Test public void unavailableNonviableAndStaleEvidenceFailClosed(){BuyReplacementQuantityRoundTripCompletionEvaluator e=new BuyReplacementQuantityRoundTripCompletionEvaluator();assertNull(e.evaluate(null,1100));assertNull(e.evaluate(source(),1221));}
 @Test public void contractsCarryNoCalibrationEconomicsRankingSelectionOrAuthorization()throws Exception{for(String f:new String[]{"BuyReplacementQuantityRoundTripCompletionEvaluation.java","BuyReplacementQuantityRoundTripCompletionEvaluationSet.java"}){String s=java.nio.file.Files.readString(java.nio.file.Path.of("src/main/java/com/flippingfriend/companion/"+f));for(String x:new String[]{"FillModel","FillEstimate","FillCurve","correctedHours","expectedSlotHours","unwindLoss","PortfolioCandidate","selected","preferred","winner","rank","PolicyDecision","OfferLifecycleAction","REPLACEMENT_AUTHORIZED"})assertFalse(s.contains(x));}}
 static BuyReplacementQuantityRoundTripCompletionEvaluationSet evaluationSetForCompanionTests(){return new BuyReplacementQuantityRoundTripCompletionEvaluator().evaluate(source(),1100);} private static BuyReplacementQuantityFillViabilityAssessment source(){return BuyReplacementQuantityFillViabilityEvaluatorTest.quantityFillViabilityAssessmentForCompanionTests();}
}
